  expiry_prediction:{title:'Expiry Range Context',eyebrow:'ESTIMATE - NOT FORECAST',purpose:'Show a same-expiry research interval, max-pain reference, OI walls, component agreement and data quality without promising a destination.',color:'#9b5b14',state:'WAIT_CHAIN_PARTIAL',metrics:[['Spot fixture','24,690'],['Max pain','24,650'],['Range estimate','24,420-24,980'],['Data quality','PARTIAL']],bars:[['Component agreement',68,'amber'],['Range coverage',61,'blue'],['Pain sensitivity',74,'purple'],['Surface quality',45,'amber']],columns:['Underlying','Bundle','Max pain','Estimated range','Agreement / quality','State'],rows:[['NIFTY','RUN-1042-A','24,650','24,420-24,980','68 / 45','WAIT'],['BANKNIFTY','RUN-1042-B','53,500','52,900-54,050','61 / 52','WAIT'],['TATASTEEL','MIXED SNAPSHOT','UNKNOWN','UNKNOWN','UNKNOWN','WAIT_CHAIN']],sources:'verified same-expiry Strike Explorer surface and versioned range formulas',formula:'EXPIRY_CONTEXT_V0 with feature-specific eligibility and sensitivity',ceiling:'OPTIONS CONTEXT ONLY',note:'Mixed expiry or snapshot bundles block the range. Max pain and OI walls are reference levels, not expiry destinations, entries or targets.',engines:[['Max-pain engine','Conventional payout reference','OPTIONS_PACKAGE','REFERENCE'],['Range engine','Eligible straddle and wall envelope','OPTIONS_PACKAGE','ESTIMATE'],['Contribution resolver','Agreement and missing components','EXPLAINABILITY','RESEARCH'],['Surface gate','Identity, coverage, quote age and expiry','HARD_VETO','STATE CEILING']]},  swing_finder:{title:'Swing Finder',eyebrow:'CLOSED-BAR SWING SHORTLIST',purpose:'Find multi-session candidates using structure, delivery, sponsor events and optional PK shadow tags.',color:'#147b67',state:'WAIT_SOURCE_ACTIVATION',metrics:[['Candidates','2 fixture'],['Delivery ready','1'],['Structure ready','2'],['Ceiling','WATCH / WAIT']],bars:[['Multi-day structure',81,''],['Delivery quality',69,'blue'],['Sponsor support',58,'purple'],['Safety readiness',46,'amber']],columns:['Symbol','Structure','Delivery','RVol','Entry state','Next proof'],rows:[['TATASTEEL','Bullish Bat','58%','3.2x','WAIT','Daily close + activation'],['HINDALCO','HH / HL','55%','2.1x','WATCH','Breakout hold'],['RELIANCE','Invalidated','31%','1.1x','REJECT','New structure required']],sources:'daily OHLCV, bhav delivery, announcements, PIT/Reg29, PK VCP shadow',formula:'SWING_FINDER_V0',ceiling:'CLOSED BAR REQUIRED',note:'Delivery and accumulation are swing evidence. They cannot confirm an intraday setup, and unclosed candles cannot permanently qualify a candidate.',engines:[['Swing discovery','Cheap multi-day filters','PARTICIPATION','ATTENTION'],['Structure','Closed daily/weekly pattern','PRICE_STRUCT','DIRECTION OWNER'],['Sponsor evidence','Named filings and deals','SPONSOR_EVENT','SUPPORT'],['Safety gate','Actions, surveillance, freshness','HARD_VETO','STATE CEILING']]},
  speculation_movers:{title:'Speculation Movers',eyebrow:'HIGH-ACTIVITY / LOW-DELIVERY CONTRAST',purpose:'Separate fast speculative activity from genuine delivery-backed accumulation before the trader opens a chart.',color:'#ad3038',state:'RESEARCH_SHADOW_ONLY',metrics:[['Highest RVol','4.0x'],['Largest range','5.8%'],['Low delivery flags','2'],['Ceiling','ATTENTION']],bars:[['Session activity',88,'amber'],['Range expansion',79,'blue'],['FO rank',72,'purple'],['Delivery support',24,'amber']],columns:['Symbol','RVol','Range','FO activity rank','Delivery','Tag'],rows:[['SBIN','4.0x','3.1%','#3','29%','SPECULATION'],['INFY','2.4x','5.8%','#7','24%','SPECULATION'],['TATASTEEL','3.2x','2.9%','#5','58%','ACTIVITY + DELIVERY']],sources:'volume gainers, most active by value/volume, FO lists, bhav delivery',formula:'SPECULATION_MOVERS_V0',ceiling:'DISCOVERY ONLY',note:'High activity plus low delivery is a speculation tag, not accumulation and not a guaranteed reversal. Use it to prioritize risk inspection.',engines:[['Activity scanner','RVol, range and turnover rank','PARTICIPATION','ATTENTION'],['FO join','Futures/options activity rank','OPT_FLOW','CONTEXT'],['Delivery contrast','Delivery / traded quantity','ACCUMULATION','CLASSIFIER'],['Resolver','Separates activity from sponsor','FUSION','EXPLAIN']]},
  trend_accumulation:{title:'Trend + Accumulation',eyebrow:'CLOSED SWING STRUCTURE PLUS EOD DELIVERY',purpose:'Combine closed multi-day structure with official EOD delivery evidence while keeping directional class, readiness and public state separate.',color:'#347a45',state:'WAIT_SOURCE_ACTIVATION',metrics:[['Trend aligned','2 fixture'],['Accumulation aligned','1'],['Setup ready','1'],['Mode','NSE SWING']],bars:[['Closed structure',76,''],['Delivery evidence',72,'blue'],['Compression',64,'purple'],['Sponsor evidence',55,'amber']],columns:['Symbol','Direction','Delivery / RVol','Readiness','Research geometry','Public state'],rows:[['TATASTEEL','Bull','58% / 3.2x','SETUP_READY','155.25 / 149.35 / 159.40','WAIT'],['HINDALCO','Bull','55% / 2.1x','DEVELOPING','714 / 698 / 738','WATCH'],['INFY','Bear','24% / 1.3x','INVALIDATED','No long geometry','REJECT']],sources:'closed daily OHLCV, official bhav delivery, structure/harmonic and named sponsor events',formula:'TREND_ACCUMULATION_V0 on one frozen adjusted-price bundle',ceiling:'SWING RESEARCH ONLY',note:'SETUP_READY is not CONFIRMED. Entry, invalidation and targets are non-executable research geometry with no quantity, account or order semantics.',engines:[['Trend engine','Closed-bar structure','PRICE_STRUCT','DIRECTION OWNER'],['Accumulation engine','EOD delivery and price co-move','ACCUMULATION','SUPPORT'],['Compression engine','Range and volatility context','PRICE_STRUCT','SETUP'],['Evidence gate','Sponsor, freshness and safety','HARD_VETO','STATE CEILING']]},  accumulation_signals:{title:'Accumulation Signals',eyebrow:'DELIVERY-FIRST SWING BOARD',purpose:'Highlight rising delivery with stable or rising price and named ownership evidence, while excluding pure volume spikes.',color:'#2e7c8a',state:'WAIT_EOD_DELIVERY',metrics:[['Delivery leaders','2 fixture'],['Named sponsor hits','1'],['Pure spikes excluded','2'],['Cadence','EOD']],bars:[['Delivery persistence',74,''],['Price hold',68,'blue'],['Named sponsor',52,'purple'],['EOD completeness',83,'amber']],columns:['Symbol','Delivery trend','Price behavior','Ownership / deal','Exclusion check','State'],rows:[['TATASTEEL','Rising 3 sessions','Holding gains','Named block deal','PASS','WAIT'],['HINDALCO','Rising 2 sessions','Higher lows','No named event','PASS','WATCH'],['SBIN','Low / falling','Fast range','No named event','PURE SPIKE','EXCLUDE']],sources:'bhav delivery, BSE/NSE PIT and Reg29, bulk/block deals',formula:'ACCUMULATION_SIGNAL_V0',ceiling:'EOD SWING CONTEXT',note:'Aggregate FII flow is not stock-level sponsor proof. A valid board keeps named filings separate from sector or market-wide institutional context.',engines:[['Delivery engine','Multi-session delivery ratio','ACCUMULATION','SUPPORT'],['Price co-move','Hold or rise with delivery','PRICE_STRUCT','CONTEXT'],['Ownership parser','Named PIT/Reg29 transactions','SPONSOR_EVENT','SPONSOR'],['Spike filter','Reject low-delivery churn','PARTICIPATION','EXCLUSION']]},
